    {
      "label": "T_Advertisement",
      "span": "to get out of the ad, you have to go into the play store, which then uses even more data",
      "rule_applied": "Definition: 'Compelled to view advertisements or incentivized to do so through the promise of rewards.'",
      "rationale": "The ad cannot be exited normally; its only dismissal route sends the player into the Play Store, compelling engagement with the ad and forcing the player through an external store page to escape it."
    }
  ],
  "invoked_web_search": false,
